import {kgFrom,number} from './calculations.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const parklandSource='https://www.ncbi.nlm.nih.gov/books/NBK609549/';
export const shockSource='https://pubmed.ncbi.nlm.nih.gov/8092595/';
export const ruleOfNines=[['Head / neck',9,18],['Anterior trunk',18,18],['Posterior trunk',18,18],['Each arm',9,9],['Each leg',18,14],['Genitals / perineum',1,null]];
export function shockIndex(hr,sbp){const h=number(hr),s=number(sbp);const value=h>0&&s>0?h/s:null;return Number.isFinite(value)?value:null;}
export function parkland(weight,unit,tbsa){const kg=kgFrom(weight,unit),area=number(tbsa);if(kg===null||area===null||area<=0||area>100)return null;const total=4*kg*area;if(!Number.isFinite(total))return null;return {kg,total,first8:total/2,next16:total/2};}
const display=n=>Number(n.toFixed(1)).toLocaleString('en-US',{maximumFractionDigits:1});
const clock=time=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(time));
export function traumaActions(fields,source,icon){return `<section class="trauma-events" aria-label="Trauma timestamps">${[['alert','Called trauma alert','trauma-alert-at','Record when the alert is called.'],['txa','GIVE TXA','trauma-txa-at','Tap when TXA starts to record the time.']].map(([event,label,key,hint])=>{const at=fields[key],recorded=Number.isFinite(at)&&at>0;return `<div class="trauma-event"><button class="trauma-event-button" data-trauma-event="${event}" aria-label="${label}" ${recorded?'disabled':''}>${icon(event==='alert'?'pulse':'syringe')}<span><b>${label}</b><small>${recorded?'Recorded':'Tap to timestamp'}</small></span></button><div class="trauma-event-time" role="status">${recorded?`<time datetime="${new Date(at).toISOString()}">${event==='txa'?'TXA started':'Alert called'} · ${clock(at)}</time><button data-clear-trauma-event="${event}" aria-label="Clear ${event==='txa'?'TXA':'trauma alert'} timestamp">Clear time</button>`:`<span>${hint}</span>`}</div>${event==='txa'?`<div class="txa-links">${source('TXA CRITERIA · S506',144)}${source('TXA EXCLUSIONS · S506',145)}</div>`:''}</div>`;}).join('')}<p class="trauma-event-help">Confirm TXA criteria, exclusions, and injury time before administration. Times record your tap and stay with this encounter.</p></section>`;}
export function shockPanel(fields,source,icon){const value=shockIndex(fields['shock-hr'],fields['shock-sbp']);return `<section class="panel shock-panel" aria-labelledby="shock-title"><div class="section-top"><h2 id="shock-title">${icon('pulse')} Shock index</h2><span class="clinical-formula">HR ÷ systolic BP</span></div><div class="shock-fields"><label class="field" for="shock-hr">Heart rate · bpm<input id="shock-hr" data-clinical-field="shock-hr" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['shock-hr'])}" placeholder="e.g. 120"></label><label class="field" for="shock-sbp">Systolic BP · mmHg<input id="shock-sbp" data-clinical-field="shock-sbp" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['shock-sbp'])}" placeholder="e.g. 100"></label><div class="shock-result" role="status"><span>SHOCK INDEX</span><strong>${value===null?'—':value.toFixed(2)}</strong></div></div><p class="clinical-help">${value===null?'Enter a heart rate and systolic BP greater than zero.':'Use with perfusion, vital-sign trends, and age.'}</p><div class="clinical-links">${source('SHOCK · SB205',53)}<a class="clinical-reference" href="${shockSource}" target="_blank" rel="noopener">Formula reference ↗</a></div></section>`;}
export function burnsPanel(fields,source,icon){const result=parkland(fields['burn-weight'],fields['burn-unit']||'kg',fields['burn-tbsa']);return `<details class="burns-panel" data-clinical-open="burns" ${fields['burns-open']?'open':''}><summary><span class="burns-icon">${icon('burns')}</span><span><b>Burns</b><small>Priorities · rule of 9s · Parkland formula</small></span><span class="burns-expand">+</span></summary><div class="burns-content"><div class="clinical-links">${source('BURN PROTOCOL · S502',139)}${source('AIRWAY · T705',189)}</div><section class="burn-priorities"><h2>First priorities</h2><ul><li>Protect the airway; assess smoke inhalation and respiratory distress.</li><li>Stop the burning process; remove affected clothing and constricting jewelry.</li><li>Cover burns with a clean, dry sheet. Keep the patient warm.</li><li>Assess associated trauma and consider CO / cyanide exposure.</li><li>Provide pain care; transport to an appropriate facility and notify it.</li></ul></section><section class="burn-rule"><div class="section-top"><h2>Rule of 9s</h2><span class="clinical-formula">% of total body surface area</span></div><p class="clinical-help">Count partial- and full-thickness burns only. Each percentage covers the whole listed region, front and back where applicable.</p><div class="burn-table-wrap"><table class="burn-table"><thead><tr><th>Region</th><th>Adult</th><th>Child · S502</th></tr></thead><tbody>${ruleOfNines.map(([region,adult,child])=>`<tr><td>${region}</td><td>${adult}%</td><td>${child===null?'Not listed':child+'%'}</td></tr>`).join('')}</tbody></table></div><p class="clinical-help">The patient’s whole palmar hand surface is approximately 1%. Use age-appropriate assessment for children.</p></section><section class="parkland-section"><div class="section-top"><h2>Parkland formula</h2><span class="clinical-formula">Classic 4 mL reference</span></div><p class="parkland-formula">4 mL × weight (kg) × % TBSA</p><div class="parkland-fields"><label class="field" for="burn-weight">Patient weight<div class="weight-entry"><input id="burn-weight" data-clinical-field="burn-weight" type="number" min="0" step="any" inputmode="decimal" value="${esc(fields['burn-weight'])}" placeholder="Weight"><select id="burn-unit" data-clinical-field="burn-unit" aria-label="Burn weight unit"><option value="kg" ${fields['burn-unit']!=='lb'?'selected':''}>kg</option><option value="lb" ${fields['burn-unit']==='lb'?'selected':''}>lb</option></select></div></label><label class="field" for="burn-tbsa">Partial / full-thickness burn · % TBSA<input id="burn-tbsa" data-clinical-field="burn-tbsa" type="number" min="0" max="100" step="any" inputmode="decimal" value="${esc(fields['burn-tbsa'])}" placeholder="e.g. 20"></label></div><div class="parkland-result" role="status">${result?`<div><span>FIRST 24 HOURS</span><strong>${display(result.total)} <small>mL</small></strong></div><div><span>FIRST 8 HOURS · ½</span><strong>${display(result.first8)} <small>mL</small></strong></div><div><span>NEXT 16 HOURS · ½</span><strong>${display(result.next16)} <small>mL</small></strong></div>`:'<p>Enter a positive weight and burn area greater than 0%, up to 100%.</p>'}</div><p class="clinical-help">Time starts at the burn injury. This reference estimates 24-hour resuscitation volume; adjust to clinical response. Children need separate maintenance-fluid consideration.</p><p class="burn-field-plan">Use <b>S502</b> for field treatment and age-based crystalloid rates.</p><a class="clinical-reference" href="${parklandSource}" target="_blank" rel="noopener">Parkland reference · WHO ↗</a></section></div></details>`;}
export function bindClinicalTools(getState,save,render){
 function refresh(el){const y=window.scrollY,id=el?.id;render();window.scrollTo(0,y);if(id)document.getElementById(id)?.focus({preventScroll:true});}
 document.addEventListener('input',e=>{if(e.target.dataset.clinicalField&&e.target.tagName==='INPUT'){getState().fields[e.target.dataset.clinicalField]=e.target.value;save();refresh(e.target);}});
 document.addEventListener('change',e=>{if(e.target.dataset.clinicalField&&e.target.tagName==='SELECT'){getState().fields[e.target.dataset.clinicalField]=e.target.value;save();refresh(e.target);}});
 document.addEventListener('toggle',e=>{if(e.target.dataset?.clinicalOpen==='burns'){getState().fields['burns-open']=e.target.open;save();}},true);
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const event=b.dataset.traumaEvent||b.dataset.clearTraumaEvent;if(!['alert','txa'].includes(event))return;const key=`trauma-${event}-at`,fields=getState().fields;if(b.dataset.clearTraumaEvent)delete fields[key];else if(!fields[key])fields[key]=Date.now();save();refresh();document.querySelector(`[${b.dataset.clearTraumaEvent?'data-trauma-event':'data-clear-trauma-event'}="${event}"]`)?.focus({preventScroll:true});});
}
